O=pathlib.Path(__file__).resolve().parent;ROOT=O.parents[4];P=O.parent/'interface_runtime/replay_r01';W=O.parent/'public_water/frozen_r01';read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();water=read(W/'routes.json');prep=read(P/'prepared.json');result=read(P/'evidence/runtime_r01/capsule.json');audit=read(P/'evidence/runtime_r01/audit.json');assert audit['status']=='PASS';pr={r['id']:r for r in prep['routes']};rr={r['id']:r for r in result['routes']};rows=[]
