 rid=r['id'];assert pr[rid]['points']==r['points_xyz_m'];assert pr[rid+'_REVERSE']['points']==r['points_xyz_m'][::-1];cases=[x for x in rr if x.startswith(rid.split(':PUBLIC_APPROACH')[0]+':')];assert len(cases)==12 and all(rr[i]['pass'] for i in cases);rows.append({'id':rid,'frozen_route_exact_parity':True,'positive_directional_cases':len(cases),'passed':len(cases),'checks':['center approach and reverse','two lateral offset approaches and reverse','old public road through and reverse','both public road turns and reverse'],'actual_branch_length_m':next(x['actual_branch_length_m'] for x in read(O/'actual_water_branch_distances.json')['actual_draw_candidates'] if x['id']==rid)})
